import{at as e,it as t,t as n,yt as r}from"./chunks/framework.DB37bP8J.js";var i=JSON.parse(`{"title":"PolarisMode With Ember and React","description":"Learn why an app rendering Ember and React on the same page can share a WarpDrive store in LegacyMode, and which Model fields won't re-render React components.","frontmatter":{"title":"PolarisMode With Ember and React","description":"Learn why an app rendering Ember and React on the same page can share a WarpDrive store in LegacyMode, and which Model fields won't re-render React components."},"headers":[],"relativePath":"guides/faq/polaris-mode-with-ember-and-react.md","filePath":"guides/faq/polaris-mode-with-ember-and-react.md"}`),a={name:`guides/faq/polaris-mode-with-ember-and-react.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="do-i-need-polarismode-to-share-state-between-ember-and-react-on-the-same-page" tabindex="-1">Do I need PolarisMode to share state between Ember and React on the same page? <a class="header-anchor" href="#do-i-need-polarismode-to-share-state-between-ember-and-react-on-the-same-page" aria-label="Permalink to “Do I need PolarisMode to share state between Ember and React on the same page?”">​</a></h1><p>No. An app that renders both Ember and React on the same page can share one store between them while using <a href="/pr-preview/pr-11291/guides/the-manual/schemas/resources/legacy-mode">LegacyMode</a>, the schema mode that emulates Models, rather than switching to <a href="/pr-preview/pr-11291/guides/the-manual/schemas/resources/polaris-mode">PolarisMode (preview)</a>. See <a href="/pr-preview/pr-11291/guides/configuration/react">Setup - React</a> for giving React components access to the store.</p><p>We recommend that apps without Ember avoid LegacyMode because legacy features such as Models, Adapters and Serializers are built on <code>EmberObject</code>. Using them means shipping <code>ember-source</code> and Ember&#39;s reactivity system, a large cost in bundle size and performance for an app that doesn&#39;t otherwise use Ember (see <a href="/pr-preview/pr-11291/guides/the-manual/schemas/resources/legacy-mode#drawbacks-of-using-legacymode">Drawbacks of Using LegacyMode</a>). When Ember is already on the page, the app has already paid that cost, so LegacyMode adds little on top of it.</p><h2 id="watch-out-for-computed-and-tracked-on-models" tabindex="-1">Watch Out For <code>@computed</code> and <code>@tracked</code> on Models <a class="header-anchor" href="#watch-out-for-computed-and-tracked-on-models" aria-label="Permalink to “Watch Out For @computed and @tracked on Models”">​</a></h2><p>The fields WarpDrive defines for a Model, such as <code>@attr</code>, <code>@belongsTo</code> and <code>@hasMany</code>, use <strong><em>Warp</em>Drive</strong>&#39;s own signals, so React components that read them re-render when they change. Properties you add to a Model yourself with Ember&#39;s <code>@computed</code> or <code>@tracked</code> don&#39;t use those signals. Ember templates still update when they change, but React components that read them won&#39;t re-render.</p><div class="tip custom-block"><p class="custom-block-title">🔭 Coming Soon</p><p><strong><em>Warp</em>Drive</strong> uses signal decorators internally to define reactive fields. Watch the <a href="/pr-preview/pr-11291/rfcs/">RFCs</a> for an upcoming proposal to make them public, so apps can define properties that re-render in any framework.</p></div>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};